PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?releaseDate WHERE {
  VALUES ?film { dbr:Edurinti_Mogudu_Pakkinti_Pellam dbr:Family_of_Strangers }

  OPTIONAL { ?film dbp:released ?date1 . }
  OPTIONAL { ?film dbo:releaseDate ?date2 . }

  BIND (COALESCE(?date1, ?date2) AS ?releaseDate)
}
LIMIT 100

